select id, session_id, event_type, count(duration_sec) over (partition by page order by duration_sec, id rows between unbounded preceding and current row) as running_count_duration_sec, max(duration_sec) over (partition by page order by duration_sec, id rows between unbounded preceding and current row) as running_max_duration_sec, avg(duration_sec) over (partition by page order by duration_sec, id rows between unbounded preceding and current row) as running_avg_duration_sec, sum(duration_sec) over (partition by page order by duration_sec, id rows between unbounded preceding and current row) as running_sum_duration_sec, row_number() over (order by duration_sec desc, id) as seq_no from web_events where session_id = 39
